float sdSphere ( vec3 p , float s){
    return length(p) - s;
}
float sdTorus( vec3 p, vec2 t )
{
  vec2 q = vec2(length(p.xz)-t.x,p.y);
  return length(q)-t.y;
}

vec3 rot3D(vec3 p, vec3 axis, float angle) {

    return mix(dot(axis, p) * axis, p, cos(angle)) 
         + cross(axis, p) * sin(angle);
}

vec3 hsv2rgb(vec3 c) {
    vec4 K = vec4(1.0, 2.0 / 3.0, 1.0 / 3.0, 3.0);
    vec3 p = abs(fract(c.xxx + K.xyz) * 6.0 - K.www);
    return c.z * mix(K.xxx, clamp(p - K.xxx, 0.0, 1.0), c.y);
}



float sdOctahedron( vec3 p, float s )
{
  p = abs(p);
  float m = p.x+p.y+p.z-s;
  vec3 q;
       if( 3.0*p.x < m ) q = p.xyz;
  else if( 3.0*p.y < m ) q = p.yzx;
  else if( 3.0*p.z < m ) q = p.zxy;
  else return m*0.57735027;

  float k = clamp(0.5*(q.z-q.y+s),0.0,s); 
  return length(vec3(q.x,q.y-s+k,q.z-k)); 
}

float map(vec3 p) {
    vec3 octPos = vec3(0, 0.0, 0.0); // Moving position

    // Rotate the Octahedron using Rodrigues' rotation formula
    float angle = iTime*1. + 2.5; // Rotation over time
    vec3 axis = normalize(vec3(1.0, 1.0, 1.0)); // Rotation axis (diagonal)
    vec3 rotatedP = rot3D(p - octPos, axis, angle); // Apply rotation
    //return sdTorus(rotatedP, vec2(1.0,0.3));
    return sdOctahedron(rotatedP, 1.0);
    //return max(sdOctahedron(rotatedP, 1.0) ,sdTorus(rotatedP, vec2(0.9,1)));;
}

vec3 calcNormal(vec3 p) {
    vec2 e = vec2(0.001, 0.0); 
    float dx = map(p + vec3(e.x, e.y, e.y)) - map(p - vec3(e.x, e.y, e.y));
    float dy = map(p + vec3(e.y, e.x, e.y)) - map(p - vec3(e.y, e.x, e.y));
    float dz = map(p + vec3(e.y, e.y, e.x)) - map(p - vec3(e.y, e.y, e.x));
    return normalize(vec3(dx, dy, dz));
}




void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = (fragCoord * 2. - iResolution.xy)/ iResolution.y;

    // init a Ray


    vec3 ro = vec3(0,0,-3); // ray origin
    vec3 rd = normalize( vec3(uv,1.) ); // ray direction vector
    vec3 col = vec3(0);
    bool hit = false;

    vec3 hitpos;
    vec3 normal;

    float t = 0.; // total distance travelled

    // Raymarching
    for (int i = 0; i < 80; i++){
        vec3 p = ro + rd * t; // current ray position
        float d = map(p);

        // col = vec3(i)/80.; Iteration Count Buffer
        if (d < 0.001 ) {
            hit = true;
            hitpos = p;
            normal = calcNormal(hitpos);
        }
        t += d; 
        if (t > 100.) break;
    }
    if (hit){
        vec3 lightPos = vec3(2, 2,-2); 
        vec3 lightDir = normalize(lightPos - hitpos); 
        float diff = max(dot(normal, lightDir), 0.15);
        //0.5, 0, 0.7
        vec3 rainbowColor = hsv2rgb(vec3(mod((iTime + 3.8) * 0.2, 1.0), 1.0, 1.0));
        col = rainbowColor * diff; 

    }




    fragColor = vec4(col,1);
}
